// Order-18 IIR, ONE combinational sum over all taps + feedback (the long
// path grows with the order -> lower Fmax; restructure to go faster).
module iir18_v7 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [7:0] xd1;
  reg [7:0] xd2;
  reg [7:0] xd3;
  reg [7:0] xd4;
  reg [7:0] xd5;
  reg [7:0] xd6;
  reg [7:0] xd7;
  reg [7:0] xd8;
  reg [7:0] xd9;
  reg [7:0] xd10;
  reg [7:0] xd11;
  reg [7:0] xd12;
  reg [7:0] xd13;
  reg [7:0] xd14;
  reg [7:0] xd15;
  reg [7:0] xd16;
  reg [7:0] xd17;
  reg [15:0] y2;
  always @(posedge clk) begin
    if (!rst_n) begin
      y<=0; y2<=0; xd1<=0; xd2<=0; xd3<=0; xd4<=0; xd5<=0; xd6<=0; xd7<=0; xd8<=0; xd9<=0; xd10<=0; xd11<=0; xd12<=0; xd13<=0; xd14<=0; xd15<=0; xd16<=0; xd17<=0;
    end else begin
      y2 <= ((192*x + (25*xd1) + (26*xd2) + (46*xd3) + (49*xd4) + (16*xd5) + (8*xd6) + (15*xd7) + (31*xd8) + (37*xd9) + (52*xd10) + (6*xd11) + (54*xd12) + (60*xd13) + (33*xd14) + (33*xd15) + (62*xd16) + (48*xd17)) & 65535);
      y <= y2;
      xd17<=xd16; xd16<=xd15; xd15<=xd14; xd14<=xd13; xd13<=xd12; xd12<=xd11; xd11<=xd10; xd10<=xd9; xd9<=xd8; xd8<=xd7; xd7<=xd6; xd6<=xd5; xd5<=xd4; xd4<=xd3; xd3<=xd2; xd2<=xd1; xd1 <= x;
    end
  end
endmodule
